// scene3d/diag/combat.js — CombatManeuverTable lookup observability
//
// Observes the CMT lookup pipeline (`ui/ac_combat_maneuver.js`) — load
// lifecycle, hit/miss rates per (stance, attackHeight, attackType)
// tuple, and which motion u32s the dispatch resolves to. Useful for
// confirming the placeholder `setSwingPose` vibe-pose path is no
// longer firing and that real motions come back from the table.
//
// Hooks fire from `ui/ac_combat_maneuver.js` at success/fail of
// loadCombatManeuverTable + hit/miss inside getCombatManeuver.

import { getCombatDiagSnapshot } from "../../ui/ac_combat_maneuver.js";

const DEFAULT_MAX_FAILURES = 20;
const DEFAULT_MAX_MISSES = 100;
const DEFAULT_MAX_HITS_SAMPLE = 50;

// Lazy fetch + cache of the MotionCommand u32 → name table generated by
// `scripts/gen-motion-command-names.cjs`. Used only to humanize the
// motion-u32 histogram in snapshot() output. Failures are non-fatal — if
// the fetch errors the diag falls back to raw hex.
let _motionNamesPromise = null;
let _motionNames = null;
function _ensureMotionNamesLoaded() {
  if (_motionNamesPromise) return _motionNamesPromise;
  _motionNamesPromise = fetch("./data/motion-command-names.json", { cache: "force-cache" })
    .then((r) => r.ok ? r.json() : null)
    .then((j) => { _motionNames = j || null; return _motionNames; })
    .catch(() => { _motionNames = null; return null; });
  return _motionNamesPromise;
}

function errStr(e) {
  if (e == null) return "(null)";
  if (typeof e === "string") return e;
  if (e.message) return String(e.message);
  try { return String(e); } catch (_) { return "(unstringifiable)"; }
}

function hexId(d) { return "0x" + ((d >>> 0).toString(16).padStart(8, "0")); }

function motionName(u32) {
  if (!_motionNames) return null;
  return _motionNames[hexId(u32)] ?? null;
}

function pushCapped(arr, entry, max) {
  arr.push(entry);
  if (arr.length > max) arr.shift();
}

// Convert Map<u32, count> → plain object keyed by hex string + joined
// against the motion-name table. Sorted by descending count for
// readability.
function _motionMapToObj(m) {
  const entries = [];
  for (const [u32, count] of m.entries()) {
    entries.push({ motion: u32 >>> 0, motionName: motionName(u32), count });
  }
  entries.sort((a, b) => b.count - a.count);
  const out = {};
  for (const e of entries) out[hexId(e.motion)] = { motionName: e.motionName, count: e.count };
  return out;
}

function _motionByStanceToObj(m) {
  const out = {};
  for (const [stance, inner] of m.entries()) {
    out[hexId(stance)] = _motionMapToObj(inner);
  }
  return out;
}

export function attachCombat(diag) {
  // Kick the motion-name table fetch eagerly so snapshot() output is
  // humanized by the time the user inspects it. Failures don't break diag.
  try { _ensureMotionNamesLoaded(); } catch (_) {}

  const combat = {
    loaded: new Map(),        // tableId → {maneuverCount, stanceCount, loadedAt}
    failures: [],
    hits: 0,
    hitsSample: [],           // ring; recent hit tuples for spot inspection
    misses: [],               // ring; recent miss tuples (with reason)
    missCountByReason: { stance: 0, height: 0, type: 0 },
    motionHistogram: new Map(),    // motion_u32 → count (resolved motions across all stances)
    motionByStance: new Map(),     // stance_u32 → Map<motion_u32, count>
    maxFailures: DEFAULT_MAX_FAILURES,
    maxMisses: DEFAULT_MAX_MISSES,
    maxHitsSample: DEFAULT_MAX_HITS_SAMPLE,

    onLoadSucceeded(meta) {
      try {
        const m = meta || {};
        const tid = (m.tableId ?? 0) >>> 0;
        combat.loaded.set(tid, {
          tableId: hexId(tid),
          maneuverCount: (m.maneuverCount ?? 0) | 0,
          stanceCount: (m.stanceCount ?? 0) | 0,
          loadedAt: performance.now(),
        });
      } catch (_) {}
    },

    onLoadFailed(meta) {
      try {
        const m = meta || {};
        pushCapped(combat.failures, {
          tableId: hexId(m.tableId ?? 0),
          error: errStr(m.error),
          source: m.source || "unknown",
          ts: performance.now(),
        }, combat.maxFailures);
      } catch (_) {}
    },

    onLookupHit(meta) {
      try {
        const m = meta || {};
        combat.hits += 1;
        const stance = (m.stance ?? 0) >>> 0;
        const motion = (m.motion ?? 0) >>> 0;
        // motion-u32 histogram (cross-stance) — Phase 1 of CMT fixes 2026-05-26.
        combat.motionHistogram.set(motion, (combat.motionHistogram.get(motion) || 0) + 1);
        // per-stance breakdown.
        let perStance = combat.motionByStance.get(stance);
        if (!perStance) { perStance = new Map(); combat.motionByStance.set(stance, perStance); }
        perStance.set(motion, (perStance.get(motion) || 0) + 1);
        pushCapped(combat.hitsSample, {
          tableId: m.tableId != null ? hexId(m.tableId) : null,
          stance,
          attackHeight: (m.attackHeight ?? 0) | 0,
          attackType: (m.attackType ?? 0) | 0,
          motion,
          motionName: motionName(motion),
          powerLevel: Number(m.powerLevel ?? 0),
          candidates: (m.candidates ?? 1) | 0,
          ts: performance.now(),
        }, combat.maxHitsSample);
      } catch (_) {}
    },

    onLookupMiss(meta) {
      try {
        const m = meta || {};
        const reason = m.reason || "unknown";
        if (reason in combat.missCountByReason) {
          combat.missCountByReason[reason] += 1;
        }
        pushCapped(combat.misses, {
          stance: (m.stance ?? 0) >>> 0,
          attackHeight: (m.attackHeight ?? 0) | 0,
          attackType: (m.attackType ?? 0) | 0,
          reason,
          ts: performance.now(),
        }, combat.maxMisses);
      } catch (_) {}
    },

    /** Read-through to the runtime's cache. */
    cached() {
      try { return getCombatDiagSnapshot(); }
      catch (_) { return { tables: [] }; }
    },

    summary() {
      const cached = combat.cached();
      return {
        tablesLoaded: combat.loaded.size,
        tablesCached: cached.tables.length,
        failures: combat.failures.length,
        hits: combat.hits,
        misses: combat.misses.length,
        missByReason: { ...combat.missCountByReason },
        motionsDistinct: combat.motionHistogram.size,
        stancesWithHits: combat.motionByStance.size,
      };
    },

    snapshot() {
      return {
        ts: new Date().toISOString(),
        loaded: Array.from(combat.loaded.values()),
        cached: combat.cached(),
        failures: [...combat.failures],
        hits: combat.hits,
        hitsSample: [...combat.hitsSample],
        misses: [...combat.misses],
        missByReason: { ...combat.missCountByReason },
        motionHistogram: _motionMapToObj(combat.motionHistogram),
        motionByStance: _motionByStanceToObj(combat.motionByStance),
        motionNamesLoaded: _motionNames != null,
      };
    },

    reset() {
      combat.failures.length = 0;
      combat.hits = 0;
      combat.hitsSample.length = 0;
      combat.misses.length = 0;
      combat.missCountByReason = { stance: 0, height: 0, type: 0 };
      combat.motionHistogram.clear();
      combat.motionByStance.clear();
    },
  };

  diag.combat = combat;
}
